"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["75398"],{17903(e){e.exports=JSON.parse('{"id":"FIN-1021","slug":"charitable-deduction","term":"Charitable Deduction","also_known_as":[],"difficulty":"Intermediate","definition":"A charitable deduction is a reduction in taxable income allowed for donations made to qualifying charities.","explanation":["Many tax systems encourage giving by letting donors reduce their taxable income by the amount given, within limits. The charity must usually be registered or approved by the tax authority.","For example, a taxpayer whose top rate of income tax is 30% gives 1,000 to a qualifying charity and deducts it. Their taxable income falls by 1,000, saving 300 in tax. The donation\'s real cost to them is 700.","In the United States, charitable donations have mainly been deductible for taxpayers who itemize, with limits based on income and the type of gift; from 2026, taxpayers who take the standard deduction can also deduct a limited amount of cash gifts. Gifts of appreciated assets, such as shares held for more than a year, can be especially tax-efficient, because the donor may avoid capital gains tax and still deduct the market value.","Other countries use different methods. In the United Kingdom, Gift Aid lets charities reclaim basic-rate tax on donations, while higher-rate taxpayers can claim extra relief. Records, such as receipts, are usually needed to support the deduction."],"note":"","total":1500,"prev":{"slug":"chargeback","term":"Chargeback"},"next":{"slug":"chart-of-accounts","term":"Chart of Accounts"}}')}}]);